ALTER TABLE public.supplier_fulfillments DROP CONSTRAINT supplier_fulfillments_provider_check;
ALTER TABLE public.supplier_fulfillments ADD CONSTRAINT supplier_fulfillments_provider_check CHECK (provider IN ('cj','dropi','manual'));
ALTER TABLE public.order_tracking_events DROP CONSTRAINT order_tracking_events_status_check;
ALTER TABLE public.order_tracking_events ADD CONSTRAINT order_tracking_events_status_check CHECK (status IN ('confirmed','preparing','packed','shipped','arrived_in_city','out_for_delivery','delivered'));
CREATE OR REPLACE FUNCTION public.capture_order_delivery_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE extra jsonb; BEGIN extra := nullif(current_setting('app.order_delivery_fields',true),'')::jsonb; IF extra IS NOT NULL AND auth.uid()=NEW.buyer_id THEN NEW.shipping_address := coalesce(NEW.shipping_address,'{}'::jsonb)||extra; END IF; RETURN NEW; END $$;
CREATE TRIGGER capture_order_delivery_fields BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.capture_order_delivery_fields();
CREATE OR REPLACE FUNCTION public.create_checkout_with_delivery(_items jsonb,_shipping_address jsonb,_shipping_quote_ids jsonb,_coupon_id uuid DEFAULT NULL,_warranty_id text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta.'; END IF; IF _shipping_address IS NOT NULL AND (length(coalesce(_shipping_address->>'cpf',''))<>11 OR length(trim(coalesce(_shipping_address->>'number','')))=0 OR length(trim(coalesce(_shipping_address->>'neighborhood','')))<2) THEN RAISE EXCEPTION 'Informe CPF, número e bairro para entrega.'; END IF; PERFORM set_config('app.order_delivery_fields',jsonb_build_object('cpf',_shipping_address->>'cpf','number',_shipping_address->>'number','neighborhood',_shipping_address->>'neighborhood')::text,true); RETURN public.create_marketplace_checkout(_items,_shipping_address,_shipping_quote_ids,_coupon_id,_warranty_id); END $$;
REVOKE ALL ON FUNCTION public.create_checkout_with_delivery(jsonb,jsonb,jsonb,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_checkout_with_delivery(jsonb,jsonb,jsonb,uuid,text) TO authenticated,service_role;